import{_ as e,o as s,c as a,a4 as o}from"./chunks/framework.DzJZdBQK.js";const p="/assets/team.BxD0im3M.png",r="/assets/team-culture.aJZTzOkn.png",c="/images/geek-time-ads/%E6%8A%80%E6%9C%AF%E7%AE%A1%E7%90%86%E5%AE%9E%E6%88%9836%E8%AE%B2.jpg",E=JSON.parse('{"title":"管理三要素","description":"","frontmatter":{"date":"2019-01-28T09:00:54","title":"管理三要素"},"headers":[],"relativePath":"posts/misc/three-factors-of-manage.md","filePath":"posts/misc/three-factors-of-manage.md"}'),n={name:"posts/misc/three-factors-of-manage.md"};function _(m,t,i,l,f,g){return s(),a("div",null,[...t[0]||(t[0]=[o('<p>在年会上董事长总结时，说到了管理的铁三角——“人-事-法”，说管理者需要从做事用人到用人做事的思想转变，因人成事，说人和事是一体两面，同时指出法是制度，是机制，是为了降低对人的依赖。这让我想起在雷.达里奥《原则》一书中，有一段对管理原则的描述，我认为他将三者的关系描述得很清楚。</p><blockquote><p>团队的价值观和原则一旦清晰明了，团队的工作方式（也就是团队文化）将渗透于团队的方方面面，包括如何制定目标、发现问题、诊断问题、设计解决方案、落实方案。人认为团队里关系应该是这样的：</p><p><img src="'+p+'" alt="团队文化"></p><p>清晰传递团队的良好文化非常重要，但这只是“魔法公式”的一半，另一半是<strong>优秀的员工</strong>，他们的价值观、能力、技能都和公司文化相得益彰。 每个公司都像一台机器，为了实现目标而运行着，这台机器会产生结果。将目标和结果进行对比，机器的操作者可以了解机器的运行状态，机器的负责人要把这种反馈循环利用好，才能更好地提升机器的性能。基于反馈，这台机器才能调整与提升。这台机器由两块组成——文化与员工。如果结果与目标不符，那机器肯定出问题了，也就是文化和员工出问题了。要让这台机器发展延续下去，就得诊断问题，设计改进方案，落实改进措施。简而言之，这个不断进化的过程如下图所示，花一分钟好好看看，自己思考一下。</p><p><img src="'+r+'" alt="团队机制"></p><p>在这台机器里，这样的过程运行得越多越有效率，进化的速度就越快。</p></blockquote><p>看了燃点，发现投资人也会更多的关注创业者的品质，认为是创始人是成事的关键。</p><p>最近在极客时间看的刘建国的《技术管理实战36讲》中，也讲到管理团队就是带人，做事，建机制。其中有一段关于“关于到底是人靠谱还是机制靠谱”</p><blockquote><p>很多管理者都认为，事情都是人做的，人如果足够靠谱，机制就没什么用了。对此，我的看法是，人的靠谱度的方差比机制大，即，人靠谱的时候比机制靠谱，人不靠谱的时候会比机制更加不靠谱。即便是最靠谱的员工，也会由于身体状态、精神状态、情绪状态以及外部干扰变得偶尔不靠谱，而机制的意义在于，当人不靠谱的时候，事情也不至于变得很差。所以，机制是为了保证做事的“下限”的。同时，机制很好的迁移性和传承性，不会随着某个人的缺倦而产生大的影响。因此，必要的机制是不可或缺的。</p></blockquote><p>而书中对如何保障机制了执行也做了提供了最少关键节点检查法，如果你对这方面的内容感兴趣，可以扫码订阅本书。 <img src="'+c+'" alt="技术管理实战36讲"></p>',6)])])}const u=e(n,[["render",_]]);export{E as __pageData,u as default};
